insert into public.expressions (id, phrase, type, register, meaning_en, meaning_es, note_es) values ('77255420-9df7-5d79-8044-cf6eb6c89ca0', 'make someone an offer they can''t refuse', 'idiom', 'informal', 'Make a proposal so attractive (or threatening) that saying no isn''t realistic.', 'Hacer una propuesta imposible de rechazar.', null) on conflict (phrase) do nothing;
insert into public.expressions (id, phrase, type, register, meaning_en, meaning_es, note_es) values ('c777e3a1-02fc-5e88-abb1-304106fd0f94', 'gonna', 'slang', 'informal', 'Spoken form of ''going to''.', 'Forma oral de ''going to'' (voy a).', 'Habitual al hablar; evítalo en textos formales.') on conflict (phrase) do nothing;
insert into public.expressions (id, phrase, type, register, meaning_en, meaning_es, note_es) values ('caaf1c1a-5cbd-538f-aac7-ca47a1508425', 'keep your friends close and your enemies closer', 'idiom', 'neutral', 'Watch your rivals carefully so you know what they are planning.', 'Vigila de cerca a tus rivales para saber qué traman.', 'Fíjate en la elipsis: ''your enemies closer'' = ''keep your enemies closer''.') on conflict (phrase) do nothing;
insert into public.expressions (id, phrase, type, register, meaning_en, meaning_es, note_es) values ('f1c161a1-1cbe-50bf-8bd0-286f2affc965', 'keep + -ing', 'grammar', 'neutral', 'Do something repeatedly or continuously.', 'No dejar de hacer algo; hacerlo una y otra vez.', 'Suele expresar fastidio: ''You keep interrupting me''.') on conflict (phrase) do nothing;
insert into public.expressions (id, phrase, type, register, meaning_en, meaning_es, note_es) values ('ccd09dcf-0537-5d26-a25d-541683aca40f', 'seize the day', 'idiom', 'neutral', 'Make the most of the present moment.', 'Aprovechar el momento.', null) on conflict (phrase) do nothing;
insert into public.expressions (id, phrase, type, register, meaning_en, meaning_es, note_es) values ('60d73416-4c9e-525f-98e7-073c0a9753de', 'make something + adjective', 'grammar', 'neutral', 'Cause something to become a certain way.', 'Hacer que algo sea de cierta manera.', null) on conflict (phrase) do nothing;
insert into public.expressions (id, phrase, type, register, meaning_en, meaning_es, note_es) values ('ca6ca616-98de-5fcb-8b14-e9906df09bb5', 'get busy + -ing', 'grammar', 'informal', 'Start doing something actively and energetically.', 'Ponerse manos a la obra con algo.', '''Let''s get busy'' = pongámonos a trabajar.') on conflict (phrase) do nothing;
insert into public.expressions (id, phrase, type, register, meaning_en, meaning_es, note_es) values ('5605b82c-45a6-5e56-aa93-f5aab39b909c', 'here''s looking at you', 'idiom', 'informal', 'A toast meaning ''to your health'' or ''this is to you''.', 'Brindis: ''¡por ti!'', ''¡a tu salud!''.', null) on conflict (phrase) do nothing;
insert into public.expressions (id, phrase, type, register, meaning_en, meaning_es, note_es) values ('dada0cfd-39d7-53be-b3f6-75f568655e30', 'you had me at ___', 'idiom', 'informal', 'You convinced me from the very first word.', 'Me convenciste desde el primer momento.', null) on conflict (phrase) do nothing;
insert into public.expressions (id, phrase, type, register, meaning_en, meaning_es, note_es) values ('ca39bb92-b903-5a8f-96c8-9b6b11b56cf7', 'make something happen', 'collocation', 'informal', 'Cause something to succeed or take place.', 'Conseguir que algo ocurra o triunfe.', null) on conflict (phrase) do nothing;
insert into public.expressions (id, phrase, type, register, meaning_en, meaning_es, note_es) values ('d8297105-c5d5-50dc-a7e7-c73936cc965f', 'stop + -ing vs. stop + to', 'grammar', 'neutral', 'Stop doing something (stop + -ing) vs. stop in order to do something (stop + to).', '''Stop trying'' = dejar de intentar; ''stop to try'' = pararse para intentar.', null) on conflict (phrase) do nothing;
insert into public.expressions (id, phrase, type, register, meaning_en, meaning_es, note_es) values ('36fa4e0f-62f3-5d7f-a182-1578915cb703', 'like (filler)', 'discourse_marker', 'slang', 'Filler word used to hesitate or soften a statement.', 'Muletilla equivalente a ''en plan'' o ''o sea''.', null) on conflict (phrase) do nothing;
insert into public.expressions (id, phrase, type, register, meaning_en, meaning_es, note_es) values ('22a18fbc-e15f-508f-853f-56fbd6d33420', 'man (vocative)', 'slang', 'slang', 'Informal way to address someone.', 'Equivalente a ''tío'' o ''colega''.', null) on conflict (phrase) do nothing;
insert into public.expressions (id, phrase, type, register, meaning_en, meaning_es, note_es) values ('66c1287a-0e89-5b47-9d52-f6e9ee62262a', 'not that + clause', 'discourse_marker', 'neutral', 'Used to deny a possible inference: ''I''m not saying that…''.', '''No es que…'': aclara lo que no quieres insinuar.', '''I can''t come — not that I wanted to.''') on conflict (phrase) do nothing;
insert into public.expressions (id, phrase, type, register, meaning_en, meaning_es, note_es) values ('2feb9bf2-444f-50e8-ac93-3024aaa0c5c8', 'come at someone', 'phrasal_verb', 'informal', 'Attack or challenge someone.', 'Ir a por alguien, atacarle.', null) on conflict (phrase) do nothing;
insert into public.expressions (id, phrase, type, register, meaning_en, meaning_es, note_es) values ('52ed1f78-9c11-5674-9001-6c54736755da', '(had) best not', 'grammar', 'informal', 'It would be wise not to; a strong warning.', 'Más te vale no…', 'Forma estándar: ''you''d better not'' o ''you had best not''.') on conflict (phrase) do nothing;
insert into public.expressions (id, phrase, type, register, meaning_en, meaning_es, note_es) values ('dc778fb8-20ca-57ca-a0e9-f49b42a36cb7', 'half-ass', 'slang', 'slang', 'Do something badly or with little effort.', 'Hacer algo a medias, de mala manera.', 'Vulgar suave: evítalo en contextos formales.') on conflict (phrase) do nothing;
insert into public.expressions (id, phrase, type, register, meaning_en, meaning_es, note_es) values ('a7c359c5-d920-5680-a5e4-1651ad25aeec', 'be on a break', 'collocation', 'informal', 'Temporarily separated in a relationship.', 'Darse un tiempo en una relación.', null) on conflict (phrase) do nothing;
