insert into public.expressions (id, phrase, type, register, meaning_en, meaning_es, note_es) values ('d02f74f4-5482-5770-8841-2c47dad002d6', '''tis but', 'grammar', 'formal', 'Archaic for ''it is only''.', 'Arcaico: ''no es más que''.', '''But'' con el sentido de ''only'' sobrevive en usos formales: ''She was but a child''.') on conflict (phrase) do nothing;
insert into public.expressions (id, phrase, type, register, meaning_en, meaning_es, note_es) values ('7e3c1958-8001-54a5-8860-7d32d9f81257', 'don''t mention the war', 'idiom', 'informal', 'Avoid a sensitive subject that could cause embarrassment.', 'Evita sacar un tema delicado.', null) on conflict (phrase) do nothing;
insert into public.expressions (id, phrase, type, register, meaning_en, meaning_es, note_es) values ('28f8b6b1-0a91-59c9-abb6-e97d7b2b91fe', 'be sucking diesel', 'idiom', 'slang', 'Making good progress; things are going well.', 'Ir sobre ruedas, avanzar a buen ritmo.', null) on conflict (phrase) do nothing;
insert into public.expressions (id, phrase, type, register, meaning_en, meaning_es, note_es) values ('c8dfe778-cb2b-5287-893f-688acb96df30', 'judgmental', 'other', 'neutral', 'Too quick to criticise others.', 'Que juzga o critica a los demás con facilidad.', 'Ortografía: ''judgmental'' (EE. UU.) o ''judgemental'' (Reino Unido).') on conflict (phrase) do nothing;
insert into public.expressions (id, phrase, type, register, meaning_en, meaning_es, note_es) values ('985162e9-6e2c-5618-aa80-7a177ca56f62', 'take on', 'phrasal_verb', 'neutral', 'Accept a task or responsibility.', 'Asumir, aceptar (un reto o una responsabilidad).', 'Otros sentidos: contratar (''take on staff'') y enfrentarse a alguien (''take on the champion'').') on conflict (phrase) do nothing;
insert into public.expressions (id, phrase, type, register, meaning_en, meaning_es, note_es) values ('e54df564-798d-59bb-9501-4f3247747eca', 'question tags', 'grammar', 'neutral', 'A short question added to seek agreement.', 'Coletilla interrogativa: ''¿verdad?'', ''¿no?''.', null) on conflict (phrase) do nothing;
insert into public.expressions (id, phrase, type, register, meaning_en, meaning_es, note_es) values ('260b82f8-6b36-5eea-b5c4-c26d1c262635', 'X is a ladder (metaphor)', 'other', 'formal', 'A situation that offers a way to climb higher.', 'Algo que sirve para ascender (metáfora).', null) on conflict (phrase) do nothing;
insert into public.expressions (id, phrase, type, register, meaning_en, meaning_es, note_es) values ('0547298d-0fcd-50eb-995f-cd9997af54a2', 'long enough to', 'grammar', 'neutral', 'For the amount of time needed to do something.', 'El tiempo suficiente para…', null) on conflict (phrase) do nothing;
insert into public.expressions (id, phrase, type, register, meaning_en, meaning_es, note_es) values ('be6377d5-3d0a-501e-a981-07234d3e6982', 'see someone + bare infinitive', 'grammar', 'neutral', 'Witness a complete action or change.', 'Ver a alguien hacer algo (acción completa, infinitivo sin ''to'').', null) on conflict (phrase) do nothing;
insert into public.expressions (id, phrase, type, register, meaning_en, meaning_es, note_es) values ('3b7c7031-2d2f-5eb8-a53b-6af5aa626851', 'with X comes Y (inversion)', 'grammar', 'formal', 'Inversion after a prepositional phrase for emphasis.', 'Inversión sujeto-verbo tras un complemento, para dar énfasis.', '''With age comes wisdom.'' El sujeto real es ''great responsibility''.') on conflict (phrase) do nothing;
insert into public.expressions (id, phrase, type, register, meaning_en, meaning_es, note_es) values ('7a6a390c-b3b6-5835-a35b-dfe64a6247f0', 'mixed conditional', 'grammar', 'neutral', 'Present unreal condition (if + past) with a past result (would have + participle).', 'Condicional mixto: condición irreal presente + consecuencia en el pasado.', null) on conflict (phrase) do nothing;
