insert into public.expressions (id, phrase, type, register, meaning_en, meaning_es, note_es) values ('0729aaad-6ab7-568d-bc29-56d9318b3dcf', 'how do you like them apples', 'idiom', 'slang', 'Said triumphantly after doing something surprising or winning.', '''¡Chúpate esa!'', ''¿qué te parece?''', null) on conflict (phrase) do nothing;
