insert into public.expressions (id, phrase, type, register, meaning_en, meaning_es, note_es) values ('f10612b0-8410-5f05-8e21-1ed618b1b81b', 'pretty + adjective', 'collocation', 'informal', '''Pretty'' as an adverb meaning ''quite'' or ''fairly''.', '''Bastante'' (no ''bonito'').', 'Falso amigo de registro: ''pretty good'' = bastante bien.') on conflict (phrase) do nothing;
insert into public.expressions (id, phrase, type, register, meaning_en, meaning_es, note_es) values ('bba53f63-942e-51e7-861f-4ace903fa807', 'contrastive stress', 'grammar', 'neutral', 'Stressing a word to contrast it with what was said before.', 'Acento contrastivo: enfatizar una palabra cambia el significado.', null) on conflict (phrase) do nothing;
insert into public.expressions (id, phrase, type, register, meaning_en, meaning_es, note_es) values ('d3197221-2598-53e7-8f03-3186572d2a6a', 'negative question (uncontracted)', 'grammar', 'formal', 'Negative question without contraction, sounding more emphatic or formal.', 'Pregunta negativa sin contraer: suena más enfática y solemne que ''Aren''t you''.', null) on conflict (phrase) do nothing;
insert into public.expressions (id, phrase, type, register, meaning_en, meaning_es, note_es) values ('b5347efb-59f2-5e94-a036-e69390219552', 'all + clause + is (cleft)', 'grammar', 'formal', 'Pseudo-cleft structure meaning ''the only thing we…''.', 'Estructura enfática: ''Lo único que… es…''.', '''All I need is time.'' Ojo: ''all'' + verbo singular ''is''.') on conflict (phrase) do nothing;
insert into public.quotes (id, work_id, text, character_name, season, episode, scene_context_es, translation_es, cultural_note_es, level, variety, status) values ('f3622fb0-c95f-5518-89a7-904be3445a9c', '0e55c1f2-2589-54be-b269-385b9311f584', 'By all means, move at a glacial pace. You know how that thrills me.', 'Miranda Priestly', null, null, 'La directora de una revista de moda reprocha a su nueva asistente que tarda demasiado en ponerse en marcha.', 'Tú tranquila, ve a paso de tortuga. Ya sabes lo que me encanta.', 'Sarcasmo frío: la frase dice lo contrario de lo que quiere decir. El tono educado lo hace aún más cortante.', 'C1', 'us', 'published') on conflict (id) do nothing;
insert into public.quote_expressions (quote_id, expression_id, start_offset, end_offset) values ('f3622fb0-c95f-5518-89a7-904be3445a9c', '778df787-aa45-5a8a-b13b-491537c6bab6', 0, 12) on conflict do nothing;
insert into public.quote_expressions (quote_id, expression_id, start_offset, end_offset) values ('f3622fb0-c95f-5518-89a7-904be3445a9c', '8be9d7cc-fa45-59a0-9dac-cdf06df5dd0c', 19, 36) on conflict do nothing;
insert into public.quote_tags (quote_id, tag_id) values ('f3622fb0-c95f-5518-89a7-904be3445a9c', '624f4274-7100-5a7c-a5cb-685c29f70350') on conflict do nothing;
insert into public.quote_tags (quote_id, tag_id) values ('f3622fb0-c95f-5518-89a7-904be3445a9c', '9cc2ab29-5edd-51b2-9544-81336846688c') on conflict do nothing;
insert into public.quotes (id, work_id, text, character_name, season, episode, scene_context_es, translation_es, cultural_note_es, level, variety, status) values ('106712d0-06a4-58ee-800d-72feebb027f7', '0e55c1f2-2589-54be-b269-385b9311f584', 'Florals? For spring? Groundbreaking.', 'Miranda Priestly', null, null, 'En una reunión, alguien propone estampados de flores para la colección de primavera.', '¿Flores? ¿En primavera? Qué revolucionario.', 'Fórmula muy usada en memes para burlarse de una idea poco original: pregunta + pregunta + adjetivo elogioso irónico.', 'C1', 'us', 'published') on conflict (id) do nothing;
