insert into public.quotes (id, work_id, text, character_name, season, episode, scene_context_es, translation_es, cultural_note_es, level, variety, status) values ('65993a2e-e6f9-5c36-9350-01df773679cc', '31847ef6-1d88-5d0a-aa64-6a110b982595', 'I''m gonna make him an offer he can''t refuse.', 'Vito Corleone', null, null, 'El jefe de la familia promete conseguir un papel para su ahijado presionando a un productor.', 'Le haré una oferta que no podrá rechazar.', 'Hoy se usa en broma para cualquier propuesta muy atractiva, aunque en la película insinúa una amenaza.', 'C1', 'us', 'published') on conflict (id) do nothing;
insert into public.quote_expressions (quote_id, expression_id, start_offset, end_offset) values ('65993a2e-e6f9-5c36-9350-01df773679cc', '77255420-9df7-5d79-8044-cf6eb6c89ca0', 10, 43) on conflict do nothing;
