insert into public.quotes (id, work_id, text, character_name, season, episode, scene_context_es, translation_es, cultural_note_es, level, variety, status) values ('65f1bf4a-fda8-55f5-a9e7-fb70a40711ef', 'fb4ff1fd-1bf0-543d-b70b-de0c72de3a3d', 'Keep your friends close, but your enemies closer.', 'Michael Corleone', null, null, 'Michael explica la estrategia que le enseñó su padre para sobrevivir en un mundo de traiciones.', 'Ten cerca a tus amigos, pero aún más cerca a tus enemigos.', null, 'C1', 'us', 'published') on conflict (id) do nothing;
insert into public.quote_expressions (quote_id, expression_id, start_offset, end_offset) values ('65f1bf4a-fda8-55f5-a9e7-fb70a40711ef', 'caaf1c1a-5cbd-538f-aac7-ca47a1508425', 0, 48) on conflict do nothing;
