insert into public.quotes (id, work_id, text, character_name, season, episode, scene_context_es, translation_es, cultural_note_es, level, variety, status) values ('4ff24a90-d463-55e3-8860-2fd70c247ff0', 'e1c493f5-5917-52f1-84dd-7fae5845fcd9', 'You keep using that word. I do not think it means what you think it means.', 'Inigo Montoya', null, null, 'Un espadachín corrige a su jefe, que repite la palabra ''inconceivable'' sin parar.', 'No paras de usar esa palabra. No creo que signifique lo que tú crees.', 'Se cita para señalar con humor que alguien usa mal un término.', 'C1', 'us', 'published') on conflict (id) do nothing;
