insert into public.quote_tags (quote_id, tag_id) values ('8ea69431-9396-5557-93d0-bdd926716616', '0686db88-e557-5e26-b18e-02ebaf8dd5b1') on conflict do nothing;
insert into public.quotes (id, work_id, text, character_name, season, episode, scene_context_es, translation_es, cultural_note_es, level, variety, status) values ('725286d4-6764-561f-b6c7-340d2b307a05', '358cc3f4-8bdd-559d-a6b4-47274cc68d31', 'Get busy living, or get busy dying.', 'Andy Dufresne', null, null, 'En la cárcel, un preso le explica a su amigo que no rendirse es una decisión.', 'O te pones a vivir, o te pones a morir.', null, 'C1', 'us', 'published') on conflict (id) do nothing;
