insert into public.quotes (id, work_id, text, character_name, season, episode, scene_context_es, translation_es, cultural_note_es, level, variety, status) values ('75602691-57f1-5ac9-a1d4-2f09ecd09613', '03d2b0d1-98c0-5b7e-9b6a-fe57933d9bd2', 'You had me at hello.', 'Dorothy Boyd', null, null, 'Él suelta un largo discurso para reconciliarse; ella le interrumpe porque ya la había convencido.', 'Me convenciste con el ''hola''.', 'Se usa en broma: ''Free pizza? You had me at free''.', 'C1', 'us', 'published') on conflict (id) do nothing;
insert into public.quote_expressions (quote_id, expression_id, start_offset, end_offset) values ('75602691-57f1-5ac9-a1d4-2f09ecd09613', 'dada0cfd-39d7-53be-b3f6-75f568655e30', 0, 13) on conflict do nothing;
