insert into public.quotes (id, work_id, text, character_name, season, episode, scene_context_es, translation_es, cultural_note_es, level, variety, status) values ('ddbef4ba-0452-5141-87a8-ac444483a489', 'df6de847-4dba-5bd4-a180-37567fc456a5', 'Never half-ass two things. Whole-ass one thing.', 'Ron Swanson', null, null, 'Un jefe de pocas palabras da un consejo sobre centrarse en una sola tarea.', 'Nunca hagas dos cosas a medias. Haz una sola a conciencia.', 'Juego de palabras: invierte el slang ''half-ass'' creando ''whole-ass''.', 'C1', 'us', 'published') on conflict (id) do nothing;
