insert into public.quote_expressions (quote_id, expression_id, start_offset, end_offset) values ('c469835a-d7d1-5361-b0be-b3c6270d64ad', 'a7c359c5-d920-5680-a5e4-1651ad25aeec', 8, 18) on conflict do nothing;
