insert into public.quotes (id, work_id, text, character_name, season, episode, scene_context_es, translation_es, cultural_note_es, level, variety, status) values ('15575be2-76e6-511b-a655-032fd112a32a', '267b3a5f-85ae-5ed5-8d23-e082cde92c50', 'I''m not a psychopath, Anderson. I''m a high-functioning sociopath.', 'Sherlock Holmes', 1, 1, 'En la escena del crimen, un forense le llama psicópata y Sherlock le corrige con desdén.', 'No soy un psicópata, Anderson. Soy un sociópata altamente funcional.', 'Corrige a otro con precisión casi médica: el tono arrogante es típico del personaje.', 'C1', 'uk', 'published') on conflict (id) do nothing;
