insert into public.quote_expressions (quote_id, expression_id, start_offset, end_offset) values ('43224a96-430b-5ea5-8739-f9992f7f2b48', 'd02f74f4-5482-5770-8841-2c47dad002d6', 0, 8) on conflict do nothing;
